import hmac
import hashlib
import base64
import json
import time
import os
from cryptography.hazmat.primitives.asymmetric import ec, utils
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend
from cryptography.exceptions import InvalidSignature

# Configuration
TOKEN_EXPIRY = 3600
ISSUER = "auth.internal.corp"
ALLOWED_ALGORITHMS = frozenset(["ES256"])

def _b64url_encode(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def _b64url_decode(data):
    if isinstance(data, str):
        data = data.encode('ascii')
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

class TokenVerifier:
    """Verifies authentication tokens using configured keys.
    Only ES256 (ECDSA with P-256) is accepted for verification.
    The server enforces the algorithm regardless of token header claims.
    """

    def __init__(self, ec_public_key_pem):
        self.ec_public_key = serialization.load_pem_public_key(
            ec_public_key_pem.encode('utf-8'),
            backend=default_backend()
        )
        self._revoked_tokens = set()
        self._nonce_cache = {}

    def revoke_token(self, token_id):
        """Add token to revocation list."""
        self._revoked_tokens.add(token_id)

    def _verify_es256(self, signing_input, signature_bytes):
        """Verify ECDSA P-256 signature."""
        try:
            self.ec_public_key.verify(
                signature_bytes,
                signing_input,
                ec.ECDSA(hashes.SHA256())
            )
            return True
        except InvalidSignature:
            return False
        except Exception:
            return False

    def verify_token(self, token_string):
        """Verify and decode an authentication token.

        Validates:
        - Token structure (3 parts, valid base64url)
        - Algorithm MUST be ES256 (server-enforced, ignores token header)
        - Cryptographic signature via ECDSA
        - Token expiration
        - Issuer claim
        - Revocation status

        Returns decoded payload dict on success, None on failure.
        """
        try:
            parts = token_string.split('.')
            if len(parts) != 3:
                return None

            header_b64, payload_b64, signature_b64 = parts

            # Decode header - but we enforce algorithm server-side
            header = json.loads(_b64url_decode(header_b64))
            declared_alg = header.get('alg')

            # CRITICAL: Server enforces algorithm. Reject anything not ES256.
            # This prevents algorithm confusion/substitution attacks.
            if declared_alg not in ALLOWED_ALGORITHMS:
                return None

            # Decode payload for validation
            payload = json.loads(_b64url_decode(payload_b64))

            # Construct signing input
            signing_input = f"{header_b64}.{payload_b64}".encode('ascii')
            signature_bytes = _b64url_decode(signature_b64)

            # Always verify with ES256 regardless of any header claim
            if not self._verify_es256(signing_input, signature_bytes):
                return None

            # Validate temporal claims
            now = time.time()
            # Require an expiration claim so tokens cannot live forever.
            if 'exp' not in payload:
                return None
            if now > payload['exp']:
                return None
            if 'nbf' in payload:
                if now < payload['nbf']:
                    return None

            # Validate issuer
            if payload.get('iss') != ISSUER:
                return None

            # Check revocation
            token_id = payload.get('jti')
            if token_id and token_id in self._revoked_tokens:
                return None

            return payload

        except (json.JSONDecodeError, ValueError, KeyError, TypeError):
            return None


class TokenIssuer:
    """Issues signed authentication tokens using ES256 only."""

    def __init__(self, ec_private_key_pem):
        self.ec_private_key = serialization.load_pem_private_key(
            ec_private_key_pem.encode('utf-8'),
            password=None,
            backend=default_backend()
        )

    def issue_token(self, subject, roles):
        """Issue a new ES256-signed token for the given subject."""
        now = time.time()

        header = {'alg': 'ES256', 'typ': 'JWT'}
        payload = {
            'sub': subject,
            'roles': roles,
            'iss': ISSUER,
            'iat': now,
            'exp': now + TOKEN_EXPIRY,
            'jti': base64.urlsafe_b64encode(os.urandom(16)).decode('ascii')
        }

        header_b64 = _b64url_encode(json.dumps(header, separators=(',', ':')).encode())
        payload_b64 = _b64url_encode(json.dumps(payload, separators=(',', ':')).encode())
        signing_input = header_b64 + b'.' + payload_b64

        signature = self.ec_private_key.sign(
            signing_input,
            ec.ECDSA(hashes.SHA256())
        )

        signature_b64 = _b64url_encode(signature)
        return (header_b64 + b'.' + payload_b64 + b'.' + signature_b64).decode('ascii')


def create_access_control_middleware(verifier):
    """Create middleware that validates tokens and enforces role-based access."""

    def check_access(token_string, required_role):
        payload = verifier.verify_token(token_string)
        if payload is None:
            return {'allowed': False, 'reason': 'invalid_token'}

        roles = payload.get('roles', [])
        if required_role not in roles:
            return {'allowed': False, 'reason': 'insufficient_privileges', 'subject': payload.get('sub')}

        return {'allowed': True, 'subject': payload.get('sub'), 'roles': roles}

    return check_access
